import { useState } from "react";
import { Link } from "react-router-dom";
import { useAuth } from "../hooks/useAuth";

export default function Connexion() {
  const { login } = useAuth();

  const [email, setEmail] = useState("");
  const [motDePasse, setMotDePasse] = useState("");

  const handleSubmit = (e) => {
    e.preventDefault();
    login({ email, motDePasse });
  };

  return (
    <div style={styles.page}>
      <div style={styles.card}>

        {/* LEFT BLUE */}
        <div style={styles.left}>
          <h2>E-Store</h2>
          <p>Bienvenue 👋</p>
          <p>Connecte-toi à ton compte</p>
        </div>

        {/* RIGHT FORM */}
        <div style={styles.right}>
          <h2>Connexion</h2>

          <form onSubmit={handleSubmit} style={styles.form}>
            <input
              type="email"
              placeholder="Email"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              style={styles.input}
              required
            />

            <input
              type="password"
              placeholder="Mot de passe"
              value={motDePasse}
              onChange={(e) => setMotDePasse(e.target.value)}
              style={styles.input}
              required
            />

            <button type="submit" style={styles.button}>
              Se connecter
            </button>
          </form>

          <p style={styles.footer}>
            Pas encore de compte ?{" "}
            <Link to="/inscription" style={styles.link}>
              S'inscrire
            </Link>
          </p>
        </div>

      </div>
    </div>
  );
}

const styles = {
  page: {
    minHeight: "100vh",
    background: "#fff",
    display: "flex",
    justifyContent: "center",
    alignItems: "center",
  },

  card: {
    display: "flex",
    width: "800px",
    borderRadius: "16px",
    overflow: "hidden",
    boxShadow: "0 10px 30px rgba(0,0,0,0.1)",
  },

  left: {
    flex: 1,
    background: "#3B5BDB",
    color: "white",
    padding: "40px",
  },

  right: {
    flex: 1,
    padding: "40px",
  },

  form: {
    display: "flex",
    flexDirection: "column",
    gap: "15px",
  },

  input: {
    padding: "12px",
    borderRadius: "8px",
    border: "1px solid #ddd",
  },

  button: {
    padding: "12px",
    background: "#3B5BDB",
    color: "white",
    border: "none",
    borderRadius: "8px",
    cursor: "pointer",
  },

  footer: {
    marginTop: "20px",
  },

  link: {
    color: "#3B5BDB",
    fontWeight: "bold",
  },
};
